 "file_path": "/tmp/t4.py",
 "content": "from lib import *
import numpy as np, sys, os
SNAP=os.environ.get('SNAP')=='1'
A=dict(k1=40,hip2=-1.4,knee2=1.3,ank2=0.0,sh=-1.0,lat=0.0,yaw=-0.35,t_arm=100,sh2=0.0,relax=1,t_rel=140,elb2=0.0)
for kv in sys.argv[1:]:
    k,v=kv.split('='); A[k]=float(v)
obs=r.reset(images=False)
cur=np.array(obs['proprio']['joint_pos'])
P=lambda **kw: pose(sh=A['sh'],lat=A['lat'],yaw=A['yaw'],**kw)
keys=[(20,P(hip=-1.0,knee=1.0,ank=0.2)),(20,P(hip=-1.3,knee=0.6,ank=0.4))]
seq=[]
for n,q in keys:
    for i in range(n): seq.append(cur+(q-cur)*(i+1)/n)
    cur=q
seq=seq[:int(A['k1'])]
t=0
def st(q):
    global t,obs
    im=['room_camera'] if (SNAP and t%60==0) else False
    obs=r.step('qpos',act(q),images=im); t+=1
    if im: Image.fromarray(obs['images']['room_camera']).save(f'/tmp/run/t4_{t:04d}.png')
    return obs['done']
for q in seq:
    if st(q): break
q1=seq[-1]; tgt=P(hip=A['hip2'],knee=A['knee2'],ank=A['ank2'])
arm=tgt.copy(); arm[[11,15]]=A['sh2']; arm[[14,18]]=A['elb2']
q=q1
while not obs['done']:
    g=obs['imu']['gravity']; jp=np.array(obs['proprio']['joint_pos'])
    if t<A['t_arm']:
        a=min(1,(t-len(seq)+1)/10); q=q1+(tgt-q1)*a
    elif t<A['t_rel']:
        a=min(1,(t-A['t_arm']+1)/30); q=tgt+(arm-tgt)*a
    elif A['relax'] and t%10==0:
        q=arm+(jp-arm)*0.5 if t<A['t_rel']+30 else q+(jp-q)*0.5
    if t%50==0 and SNAP: print(t,np.round(g,2),np.round(jp[[2,3,4,11,14]],2), 'err',np.round(np.abs(q-jp).sum(),2))
    st(q)
print(A, obs['done'],obs['reason'],obs['step'])
"
